(n, k, x) = map(int, input().split())
arr = list(map(int, input().split()))
dp = [[0 for i in range(1024)], [0 for i in range(1024)]]
for i in range(n):
	dp[0][arr[i]] += 1
for i in range(k):
	for j in range(1024):
		dp[~i & 1][j] = 0
	ctr = 0
	for j in range(1024):
		if ctr == 0:
			dp[~i & 1][j ^ x] += dp[i & 1][j] + 1 >> 1
			dp[~i & 1][j] += dp[i & 1][j] >> 1
		else:
			dp[~i & 1][j] += dp[i & 1][j] + 1 >> 1
			dp[~i & 1][j ^ x] += dp[i & 1][j] >> 1
		ctr ^= dp[i & 1][j] & 1
(minv, maxv) = (1024, 0)
for i in range(1024):
	if dp[k & 1][i] == 0:
		continue
	minv = min(minv, i)
	maxv = max(maxv, i)
print(maxv, minv)
